def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None

        major, minor, patch = (int(x) for x in main.split('.'))

        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre = 0  # has prerelease sorts before
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            pre_key = tuple(pre_key)

        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

